function paginate<T>(items: T[], page: number, pageSize: number): T[] {
  if (!Number.isInteger(page) || page < 1 || !Number.isInteger(pageSize) || pageSize < 1) throw new RangeError("Niepoprawna paginacja");
  const start = (page - 1) * pageSize;
  return items.slice(start, start + pageSize);
}

function getField<T, K extends keyof T>(item: T, key: K): T[K] { return item[key]; }
function typeCheckOnly() {
